zig
const std = @import("std");
const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("cublas_v2.h");
});

const VideoTokenizer = struct {
    patch_size: usize,
    temporal_depth: usize,
    hidden_dim: usize,
    num_codebooks: usize,
    codebook_size: usize,
    encoder_weights: []f32,
    decoder_weights: []f32,
    codebook_embeddings: []f32,
    d_encoder: c.cudaMalloc_t,
    d_decoder: c.cudaMalloc_t,
    d_codebook: c.cudaMalloc_t,
    cublas_handle: c.cublasHandle_t,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, patch_size: usize, temporal_depth: usize, hidden_dim: usize, num_codebooks: usize, codebook_size: usize) !VideoTokenizer {
        const encoder_size = patch_size * patch_size * temporal_depth * 3 * hidden_dim;
        const decoder_size = hidden_dim * patch_size * patch_size * temporal_depth * 3;
        const codebook_total = num_codebooks * codebook_size * hidden_dim;

        var encoder_weights = try allocator.alloc(f32, encoder_size);
        var decoder_weights = try allocator.alloc(f32, decoder_size);
        var codebook_embeddings = try allocator.alloc(f32, codebook_total);

        var rng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
        const random = rng.random();

        for (encoder_weights) |*w| {
            w.* = random.floatNorm(f32) * 0.02;
        }
        for (decoder_weights) |*w| {
            w.* = random.floatNorm(f32) * 0.02;
        }
        for (codebook_embeddings) |*e| {
            e.* = random.floatNorm(f32) * 0.1;
        }

        var d_encoder: c.cudaMalloc_t = undefined;
        var d_decoder: c.cudaMalloc_t = undefined;
        var d_codebook: c.cudaMalloc_t = undefined;

        _ = c.cudaMalloc(@ptrCast(&d_encoder), encoder_size * @sizeOf(f32));
        _ = c.cudaMalloc(@ptrCast(&d_decoder), decoder_size * @sizeOf(f32));
        _ = c.cudaMalloc(@ptrCast(&d_codebook), codebook_total * @sizeOf(f32));

        _ = c.cudaMemcpy(d_encoder, encoder_weights.ptr, encoder_size * @sizeOf(f32), c.cudaMemcpyHostToDevice);
        _ = c.cudaMemcpy(d_decoder, decoder_weights.ptr, decoder_size * @sizeOf(f32), c.cudaMemcpyHostToDevice);
        _ = c.cudaMemcpy(d_codebook, codebook_embeddings.ptr, codebook_total * @sizeOf(f32), c.cudaMemcpyHostToDevice);

        var cublas_handle: c.cublasHandle_t = undefined;
        _ = c.cublasCreate(&cublas_handle);

        return VideoTokenizer{
            .patch_size = patch_size,
            .temporal_depth = temporal_depth,
            .hidden_dim = hidden_dim,
            .num_codebooks = num_codebooks,
            .codebook_size = codebook_size,
            .encoder_weights = encoder_weights,
            .decoder_weights = decoder_weights,
            .codebook_embeddings = codebook_embeddings,
            .d_encoder = d_encoder,
            .d_decoder = d_decoder,
            .d_codebook = d_codebook,
            .cublas_handle = cublas_handle,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *VideoTokenizer) void {
        self.allocator.free(self.encoder_weights);
        self.allocator.free(self.decoder_weights);
        self.allocator.free(self.codebook_embeddings);
        _ = c.cudaFree(self.d_encoder);
        _ = c.cudaFree(self.d_decoder);
        _ = c.cudaFree(self.d_codebook);
        _ = c.cublasDestroy(self.cublas_handle);
    }

    pub fn encode(self: *VideoTokenizer, video_frames: []const f32, batch_size: usize, num_frames: usize, height: usize, width: usize) ![]i32 {
        const num_patches_h = height / self.patch_size;
        const num_patches_w = width / self.patch_size;
        const num_patches_t = num_frames / self.temporal_depth;
        const total_patches = batch_size * num_patches_t * num_patches_h * num_patches_w;

        var d_input: c.cudaMalloc_t = undefined;
        var d_output: c.cudaMalloc_t = undefined;
        var d_indices: c.cudaMalloc_t = undefined;

        _ = c.cudaMalloc(@ptrCast(&d_input), video_frames.len * @sizeOf(f32));
        _ = c.cudaMalloc(@ptrCast(&d_output), total_patches * self.hidden_dim * @sizeOf(f32));
        _ = c.cudaMalloc(@ptrCast(&d_indices), total_patches * self.num_codebooks * @sizeOf(i32));

        _ = c.cudaMemcpy(d_input, video_frames.ptr, video_frames.len * @sizeOf(f32), c.cudaMemcpyHostToDevice);

        const alpha: f32 = 1.0;
        const beta: f32 = 0.0;
        _ = c.cublasSgemm(self.cublas_handle, c.CUBLAS_OP_N, c.CUBLAS_OP_N, @intCast(self.hidden_dim), @intCast(total_patches), @intCast(self.patch_size * self.patch_size * self.temporal_depth * 3), &alpha, self.d_encoder, @intCast(self.hidden_dim), d_input, @intCast(self.patch_size * self.patch_size * self.temporal_depth * 3), &beta, d_output, @intCast(self.hidden_dim));

        var indices = try self.allocator.alloc(i32, total_patches * self.num_codebooks);
        var h_output = try self.allocator.alloc(f32, total_patches * self.hidden_dim);
        defer self.allocator.free(h_output);

        _ = c.cudaMemcpy(h_output.ptr, d_output, total_patches * self.hidden_dim * @sizeOf(f32), c.cudaMemcpyDeviceToHost);

        for (0..total_patches) |p| {
            for (0..self.num_codebooks) |cb| {
                var min_dist: f32 = std.math.inf(f32);
                var min_idx: i32 = 0;
                for (0..self.codebook_size) |k| {
                    var dist: f32 = 0;
                    for (0..self.hidden_dim) |d| {
                        const diff = h_output[p * self.hidden_dim + d] - self.codebook_embeddings[cb * self.codebook_size * self.hidden_dim + k * self.hidden_dim + d];
                        dist += diff * diff;
                    }
                    if (dist < min_dist) {
                        min_dist = dist;
                        min_idx = @intCast(k);
                    }
                }
                indices[p * self.num_codebooks + cb] = min_idx;
            }
        }

        _ = c.cudaFree(d_input);
        _ = c.cudaFree(d_output);
        _ = c.cudaFree(d_indices);

        return indices;
    }

    pub fn decode(self: *VideoTokenizer, indices: []const i32, batch_size: usize, num_patches_t: usize, num_patches_h: usize, num_patches_w: usize) ![]f32 {
        const total_patches = batch_size * num_patches_t * num_patches_h * num_patches_w;
        const output_size = batch_size * num_patches_t * self.temporal_depth * num_patches_h * self.patch_size * num_patches_w * self.patch_size * 3;

        var d_latents: c.cudaMalloc_t = undefined;
        var d_output: c.cudaMalloc_t = undefined;

        _ = c.cudaMalloc(@ptrCast(&d_latents), total_patches * self.hidden_dim * @sizeOf(f32));
        _ = c.cudaMalloc(@ptrCast(&d_output), output_size * @sizeOf(f32));

        var h_latents = try self.allocator.alloc(f32, total_patches * self.hidden_dim);
        defer self.allocator.free(h_latents);

        for (0..total_patches) |p| {
            for (0..self.hidden_dim) |d| {
                var sum: f32 = 0;
                for (0..self.num_codebooks) |cb| {
                    const idx = indices[p * self.num_codebooks + cb];
                    sum += self.codebook_embeddings[cb * self.codebook_size * self.hidden_dim + @as(usize, @intCast(idx)) * self.hidden_dim + d];
                }
                h_latents[p * self.hidden_dim + d] = sum / @as(f32, @floatFromInt(self.num_codebooks));
            }
        }

        _ = c.cudaMemcpy(d_latents, h_latents.ptr, total_patches * self.hidden_dim * @sizeOf(f32), c.cudaMemcpyHostToDevice);

        const alpha: f32 = 1.0;
        const beta: f32 = 0.0;
        _ = c.cublasSgemm(self.cublas_handle, c.CUBLAS_OP_N, c.CUBLAS_OP_N, @intCast(self.patch_size * self.patch_size * self.temporal_depth * 3), @intCast(total_patches), @intCast(self.hidden_dim), &alpha, self.d_decoder, @intCast(self.patch_size * self.patch_size * self.temporal_depth * 3), d_latents, @intCast(self.hidden_dim), &beta, d_output, @intCast(self.patch_size * self.patch_size * self.temporal_depth * 3));

        var output = try self.allocator.alloc(f32, output_size);
        _ = c.cudaMemcpy(output.ptr, d_output, output_size * @sizeOf(f32), c.cudaMemcpyDeviceToHost);

        _ = c.cudaFree(d_latents);
        _ = c.cudaFree(d_output);

        return output;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var tokenizer = try VideoTokenizer.init(allocator, 16, 2, 512, 4, 8192);
    defer tokenizer.deinit();

    const batch_size: usize = 1;
    const num_frames: usize = 16;
    const height: usize = 256;
    const width: usize = 256;
    const video_size = batch_size * num_frames * height * width * 3;

    var video_frames = try allocator.alloc(f32, video_size);
    defer allocator.free(video_frames);

    var rng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
    const random = rng.random();
    for (video_frames) |*f| {
        f.* = random.float(f32);
    }

    const indices = try tokenizer.encode(video_frames, batch_size, num_frames, height, width);
    defer allocator.free(indices);

    const num_patches_h = height / tokenizer.patch_size;
    const num_patches_w = width / tokenizer.patch_size;
    const num_patches_t = num_frames / tokenizer.temporal_depth;

    const reconstructed = try tokenizer.decode(indices, batch_size, num_patches_t, num_patches_h, num_patches_w);
    defer allocator.free(reconstructed);

    std.debug.print("Tokenization complete. Generated {} indices\n", .{indices.len});
}
